        /// <summary>Line_Break, pre-resolved per LB1. Codepoints not listed are AL.</summary>
        public static LineBreakClass GetLineClass(int codepoint)
        {
            int lo = 0, hi = LineStarts.Length - 1;
            while (lo <= hi)
            {
                int mid = (lo + hi) >> 1;
                if (codepoint < LineStarts[mid]) hi = mid - 1;
                else if (codepoint > LineEnds[mid]) lo = mid + 1;
                else return (LineBreakClass)LineValues[mid];
            }
            return LineBreakClass.AL;
        }

        /// <summary>Grapheme_Cluster_Break (UAX #29).</summary>
        public static GraphemeBreakClass GetGraphemeClass(int codepoint)
        {
            int lo = 0, hi = GraphemeStarts.Length - 1;
            while (lo <= hi)
            {
                int mid = (lo + hi) >> 1;
                if (codepoint < GraphemeStarts[mid]) hi = mid - 1;
                else if (codepoint > GraphemeEnds[mid]) lo = mid + 1;
                else return (GraphemeBreakClass)GraphemeValues[mid];
            }
            return GraphemeBreakClass.Other;
        }

        /// <summary>Word_Break (UAX #29).</summary>
        public static WordBreakClass GetWordClass(int codepoint)
        {
            int lo = 0, hi = WordStarts.Length - 1;
            while (lo <= hi)
            {
                int mid = (lo + hi) >> 1;
