            return SentenceBreakClass.Other;
        }

        /// <summary>Indic_Conjunct_Break, used by GB9c.</summary>
        public static IncbClass GetIncb(int codepoint)
        {
            int lo = 0, hi = IncbStarts.Length - 1;
            while (lo <= hi)
            {
                int mid = (lo + hi) >> 1;
                if (codepoint < IncbStarts[mid]) hi = mid - 1;
                else if (codepoint > IncbEnds[mid]) lo = mid + 1;
                else return (IncbClass)IncbValues[mid];
            }
            return IncbClass.None;
        }

        /// <summary>Auxiliary properties used by the break rules.</summary>
        public static CharFlags GetFlags(int codepoint)
        {
            int lo = 0, hi = FlagStarts.Length - 1;
            while (lo <= hi)
            {
                int mid = (lo + hi) >> 1;
                if (codepoint < FlagStarts[mid]) hi = mid - 1;
                else if (codepoint > FlagEnds[mid]) lo = mid + 1;
                else return (CharFlags)FlagValues[mid];
            }
            return CharFlags.None;
        }
